# Generated by scripts/scaffold_rule_tests.py; existing functions are preserved.
from __future__ import annotations

import pandas as pd
import pytest

from ml_workbench.rules.split import (
    choose_split,
    cv_strategy,
    default_holdout_fraction,
    default_n_splits,
)
from ml_workbench.rules.task import build_task, suggest_task_type
from ml_workbench.services.preprocessing_service import materialize_split
from ml_workbench.state import TaskDefinition, TaskError, feature_columns


def _task(
    *,
    learning_type: str = "supervised",
    task_type: str = "binary",
    target: str | None = None,
    group: str | None = None,
    time_column: str | None = None,
    eval_labels: str | None = None,
) -> TaskDefinition:
    if target is None:
        target = None if learning_type == "unsupervised" else "y"
    return TaskDefinition(
        learning_type=learning_type,
        task_type=task_type,
        target=target,
        group=group,
        time_column=time_column,
        eval_labels=eval_labels,
    )


def test_task_suggestion_from_target() -> None:
    binary = pd.Series([0, 1, 1, 0, 1], name="churned")
    assert suggest_task_type(binary) == "binary"

    multiclass = pd.Series([0, 1, 2, 3] * 10, name="grade")
    assert suggest_task_type(multiclass) == "multiclass"

    regression = pd.Series([float(i) for i in range(100)], name="price")
    assert suggest_task_type(regression) == "regression"

    string_labels = pd.Series(["cat", "dog", "bird"] * 5, name="species")
    assert suggest_task_type(string_labels) == "multiclass"

    edge = pd.Series([i % 20 for i in range(40)], name="y")
    assert suggest_task_type(edge) == "multiclass"
    grown = pd.Series([i % 21 for i in range(42)], name="y")
    assert suggest_task_type(grown) == "regression"

    constant = pd.Series([3] * 10, name="y")
    with pytest.raises(TaskError):
        suggest_task_type(constant)


def test_task_forecasting_requires_confirmation() -> None:
    frame = pd.DataFrame(
        {
            "date": pd.date_range("2024-01-01", periods=12, freq="MS"),
            "sales": [float(value * 1.7) for value in range(12)],
        }
    )
    ordinary = build_task(frame, "supervised", target="sales")
    assert ordinary.task_type == "regression"
    assert "date" in feature_columns(ordinary, frame)  # datetime is an ordinary feature

    with pytest.raises(TaskError):
        build_task(frame, "supervised", target="date")
    with pytest.raises(TaskError):
        build_task(frame, "supervised", target="sales", time_column="date")

    forecast = build_task(
        frame, "supervised", target="sales", time_column="date", confirm_forecasting=True
    )
    assert forecast.task_type == "forecasting"
    assert forecast.time_column == "date"


def test_unsupervised_eval_labels_never_fit() -> None:
    frame = pd.DataFrame(
        {
            "x": [1.0, 2.0, 3.0, 4.0],
            "y": [2.0, 4.0, 1.0, 5.0],
            "label": ["a", "b", "a", "b"],
        }
    )
    with pytest.raises(TaskError):
        build_task(frame, "unsupervised", target="label", task_type="clustering")
    with pytest.raises(TaskError):
        TaskDefinition(learning_type="unsupervised", task_type="clustering", target="label")

    task = build_task(frame, "unsupervised", task_type="clustering", eval_labels="label")
    assert task.target is None
    assert task.learning_type == "unsupervised"
    assert feature_columns(task, frame) == ["x", "y"]


def test_split_chronological_no_shuffle() -> None:
    task = _task(task_type="forecasting", time_column="date")
    rule = choose_split(task)
    assert rule.strategy == "chronological"
    assert rule.rule_id == "SPLIT-01"
    assert rule.shuffle is False

    frame = pd.DataFrame(
        {
            "date": pd.date_range("2024-01-01", periods=10, freq="MS"),
            "sales": [float(value) for value in range(10)],
        }
    )
    result = materialize_split(frame, task, rule, test_size=0.3, seed=0)
    assert result.train.max() < result.test.min()


def test_split_group_never_crosses_folds() -> None:
    task = _task(task_type="regression", group="group")
    rule = choose_split(task)
    assert rule.strategy == "grouped"
    frame = pd.DataFrame(
        {
            "group": ["g1"] * 6 + ["g2"] * 6,
            "value": [float(value) for value in range(12)],
        }
    )
    result = materialize_split(frame, task, rule, test_size=0.3, seed=0)
    train_groups = set(frame.iloc[result.train]["group"])
    test_groups = set(frame.iloc[result.test]["group"])
    assert result.train.size > 0
    assert result.test.size > 0
    assert train_groups.isdisjoint(test_groups)


def test_split_stratified_classification() -> None:
    rule = choose_split(_task(task_type="binary"))
    assert rule.strategy == "stratified"
    assert rule.rule_id == "SPLIT-03"
    assert rule.shuffle is True

    frame = pd.DataFrame(
        {
            "x": range(100),
            "y": [0, 1] * 50,
        }
    )
    result = materialize_split(frame, _task(task_type="binary"), rule, test_size=0.2, seed=0)
    train_share = float(frame.iloc[result.train]["y"].mean())
    test_share = float(frame.iloc[result.test]["y"].mean())
    assert abs(train_share - test_share) < 0.15
    assert abs(train_share - 0.5) < 0.1


